"""The capability API: POST creates, GET reads, tenant-scoped throughout.

Auth is resolved FIRST, from the bearer token, before any body is read:
an unauthenticated request answers 401 and never reaches validation. The
tenant comes from the principal, never from the payload -- and a record
belonging to another tenant answers 404, not 403 and not the record.

Persistence is the ROUTE's job: it saves the request the caller sent (not
the handler's envelope) under the caller's tenant. Handlers never touch the
store; they build block inputs and return a decision.
"""

from __future__ import annotations

import importlib
import json
from typing import Any, Dict

from fastapi import APIRouter, Request
from fastapi.responses import JSONResponse

from app import authority, store
from app.models import MODELS, validate
from app.security import (
    MAX_BODY_BYTES,
    MAX_STRING_LENGTH,
    not_found,
    oversized,
    payload_too_large,
    rejection,
    unauthorized,
)
from app.tenancy import resolve_tenant

router = APIRouter()

#: capability id -> the store entity it is saved to (the capability id).
ROUTE_ENTITIES: Dict[str, str] = {
    capability_id: (getattr(cls, "ENTITY", capability_id) or capability_id)
    for capability_id, cls in MODELS.items()
}


def _principal_or_none(request: Request):
    try:
        return resolve_tenant(request.headers)
    except PermissionError:
        return None
    except Exception:
        return None


def _discovery() -> list:
    """What the console reads to build its screens: the capabilities and
    the fields each one declares (never a second API)."""
    catalogue = []
    for capability_id, cls in MODELS.items():
        constraints = getattr(cls, "CONSTRAINTS", {}) or {}
        catalogue.append({
            "capability_id": capability_id,
            "entity": ROUTE_ENTITIES[capability_id],
            "required": [n for n in cls.FIELDS if (constraints.get(n) or {}).get("required")],
            "fields": [
                {
                    "name": name,
                    "type": (constraints.get(name) or {}).get("type", "str"),
                    "format": (constraints.get(name) or {}).get("format"),
                    "allowed_values": (constraints.get(name) or {}).get("allowed_values"),
                    "min": (constraints.get(name) or {}).get("min"),
                    "max": (constraints.get(name) or {}).get("max"),
                }
                for name in cls.FIELDS
            ],
        })
    return catalogue


@router.get("/v1")
async def describe_platform(request: Request):
    principal = _principal_or_none(request)
    if principal is None:
        return unauthorized()
    body = {
        "ok": True,
        "status": "ok",
        "platform": "Community Bicycle Repair Co-op Platform",
        "tenant": principal.tenant_id,
        "capabilities": _discovery(),
    }
    body.update(authority.attach("documents", [], detail="capability catalogue"))
    return JSONResponse(status_code=200, content=body)


def _load_json(raw: bytes):
    if not raw:
        return {}
    if len(raw) > MAX_BODY_BYTES:
        raise ValueError("payload too large")
    try:
        return json.loads(raw.decode("utf-8"))
    except RecursionError:
        # A deeply nested body is malformed input, not a server fault.
        raise ValueError("payload nesting too deep") from None


#: Refusals a CALLER caused: they are 4xx answers, never a 503.
CLIENT_ERROR_KINDS = frozenset({
    "missing_required", "validation_failed", "invalid_input", "invalid_state",
    "illegal_transition", "step_failed", "invalid_step", "unknown_channel",
    "not_allowed", "out_of_range", "unknown_action",
})


@router.post("/v1/{capability_id}")
async def create_capability(capability_id: str, request: Request):
    principal = _principal_or_none(request)
    if principal is None:
        return unauthorized()
    capability_id = str(capability_id)
    if capability_id not in MODELS:
        return not_found("unknown capability: %s" % capability_id)

    # Content-Length is checked before the body is buffered; the post-read
    # check stays as the backstop for a chunked request with no header.
    declared = request.headers.get("content-length")
    if declared is not None:
        try:
            if int(declared) > MAX_BODY_BYTES:
                return payload_too_large(int(declared))
        except ValueError:
            return rejection("content-length", "malformed_header", status_code=400)
    raw = await request.body()
    if len(raw) > MAX_BODY_BYTES:
        return payload_too_large(len(raw))
    try:
        payload = _load_json(raw)
    except (ValueError, UnicodeDecodeError, RecursionError):
        return rejection("payload", "malformed_json", status_code=400)
    if not isinstance(payload, dict):
        return rejection("payload", "not_an_object", status_code=400)
    if oversized(payload):
        return rejection("payload", "too_long", status_code=413)

    data, bad = validate(capability_id, payload)
    if bad is not None:
        return rejection(bad["rejected_field"], bad["rejection_reason"],
                         bad.get("allowed_values"))
    if len(json.dumps(data)) > MAX_STRING_LENGTH * 8:
        return rejection("payload", "too_long", status_code=413)

    module = importlib.import_module("app.actions." + capability_id)
    answer = module.handle(dict(data))
    if not isinstance(answer, dict) or answer.get("ok") is not True:
        error_kind = (answer or {}).get("error_kind") if isinstance(answer, dict) else None
        status = 422 if str(error_kind) in CLIENT_ERROR_KINDS else 503
        return JSONResponse(
            status_code=status,
            content={
                "ok": False,
                "status": "error",
                "capability": capability_id,
                "error": str((answer or {}).get("error") or "refused"),
                "error_kind": str(error_kind or "refused"),
            },
        )

    entity = ROUTE_ENTITIES[capability_id]
    try:
        record_id = store.save(entity, dict(data), principal.tenant_id)
    except Exception as exc:  # DBAPI/SQLAlchemy: a record the schema refuses
        return rejection("record", "unstoreable:%s" % type(exc).__name__,
                         status_code=422)
    body = {
        "ok": True,
        "status": "ok",
        "capability": capability_id,
        "entity": entity,
        "record_id": record_id,
        "stored": {"id": record_id, "entity": entity, "record": dict(data)},
        "record": dict(data),
        "decision": answer,
    }
    body.update(authority.attach(
        str(answer.get("authority", {}).get("source") or "procedures"),
        list(answer.get("claims") or []),
        detail="capability",
    ))
    return JSONResponse(status_code=200, content=body)


@router.get("/v1/{capability_id}")
async def list_capability(capability_id: str, request: Request):
    principal = _principal_or_none(request)
    if principal is None:
        return unauthorized()
    capability_id = str(capability_id)
    if capability_id not in MODELS:
        return not_found("unknown capability: %s" % capability_id)
    entity = ROUTE_ENTITIES[capability_id]
    items = store.list_all(entity, principal.tenant_id)
    body = {
        "ok": True,
        "status": "ok",
        "capability": capability_id,
        "entity": entity,
        "items": items,
        "total": len(items),
    }
    body.update(authority.attach("documents", [],
                                 detail="capability listing"))
    return JSONResponse(status_code=200, content=body)


@router.get("/v1/{capability_id}/{record_id}")
async def read_capability(capability_id: str, record_id: str, request: Request):
    principal = _principal_or_none(request)
    if principal is None:
        return unauthorized()
    capability_id = str(capability_id)
    if capability_id not in MODELS:
        return not_found("unknown capability: %s" % capability_id)
    entity = ROUTE_ENTITIES[capability_id]
    record = store.get(entity, record_id, principal.tenant_id)
    if record is None:
        return not_found("no such record")
    body = {"ok": True, "status": "ok", "capability": capability_id,
            "record": record, "record_id": record_id}
    body.update(authority.attach("documents", [], detail="capability record"))
    return JSONResponse(status_code=200, content=body)


@router.delete("/v1/{capability_id}/{record_id}")
async def delete_capability(capability_id: str, record_id: str, request: Request):
    principal = _principal_or_none(request)
    if principal is None:
        return unauthorized()
    capability_id = str(capability_id)
    if capability_id not in MODELS:
        return not_found("unknown capability: %s" % capability_id)
    entity = ROUTE_ENTITIES[capability_id]
    removed = store.delete(entity, record_id, principal.tenant_id)
    if not removed:
        return not_found("no such record")
    return JSONResponse(status_code=200,
                        content={"ok": True, "status": "ok", "deleted": removed})

