/**
 * Operator console (TypeScript source).
 *
 * The image ships this console as app/static/index.html — the same screens,
 * driven against the same routes — so the product serves one UI with no
 * npm build step in the image (the build box has no network). This file is
 * the typed source of that page: discovery from GET /v1, create through
 * POST /v1/{capability_id}, read back through GET /v1/{capability_id}, and
 * the authority label shown on every answer.
 */
import { useCallback, useEffect, useState } from "react";

type FieldSpec = {
  name: string;
  type?: string;
  format?: string | null;
  allowed_values?: string[] | null;
  min?: number | null;
  max?: number | null;
};

type Capability = {
  capability_id: string;
  entity: string;
  required: string[];
  fields: FieldSpec[];
};

type Authority = { layer?: number; layer_name?: string; precedence?: string };

type Answer = {
  ok?: boolean;
  authority?: Authority;
  error?: string;
  rejected_field?: string;
  items?: Array<Record<string, unknown>>;
  decision?: Record<string, unknown>;
};

const SAMPLE: Record<string, unknown> = {
  str: "sample",
  int: 1,
  float: 1.5,
  bool: false,
  date: "2026-09-03",
  time: "10:00:00",
  datetime: "2026-09-03T10:00:00",
  email: "guest@example.com",
};

function sampleFor(field: FieldSpec): unknown {
  if (field.allowed_values?.length) return field.allowed_values[0];
  if (field.format === "email" || field.type === "email") return SAMPLE.email;
  const type = (field.type || "str").toLowerCase();
  if (type === "money") return 1.5;
  return SAMPLE[type] ?? "sample";
}

export default function App() {
  const [token, setToken] = useState("");
  const [capabilities, setCapabilities] = useState<Capability[]>([]);
  const [selected, setSelected] = useState("");
  const [draft, setDraft] = useState<Record<string, unknown>>({});
  const [answer, setAnswer] = useState<Answer | null>(null);
  const [status, setStatus] = useState(0);

  const headers = useCallback(
    (): Record<string, string> =>
      token ? { Authorization: `Bearer ${token}`, "Content-Type": "application/json" } : { "Content-Type": "application/json" },
    [token],
  );

  const connect = useCallback(async () => {
    const response = await fetch("/v1", { headers: headers() });
    const body = (await response.json()) as { capabilities?: Capability[]; ok?: boolean };
    setStatus(response.status);
    if (response.ok && body.ok !== false) {
      setCapabilities(body.capabilities ?? []);
      setSelected(body.capabilities?.[0]?.capability_id ?? "");
    } else {
      setCapabilities([]);
      setAnswer(body as Answer);
    }
  }, [headers]);

  useEffect(() => {
    if (!selected && capabilities.length) setSelected(capabilities[0].capability_id);
  }, [capabilities, selected]);

  const capability = capabilities.find((item) => item.capability_id === selected);

  const create = useCallback(async () => {
    if (!capability) return;
    const response = await fetch(`/v1/${capability.capability_id}`, {
      method: "POST",
      headers: headers(),
      body: JSON.stringify(draft),
    });
    setStatus(response.status);
    setAnswer((await response.json()) as Answer);
  }, [capability, draft, headers]);

  const list = useCallback(async () => {
    if (!capability) return;
    const response = await fetch(`/v1/${capability.capability_id}`, { headers: headers() });
    setStatus(response.status);
    setAnswer((await response.json()) as Answer);
  }, [capability, headers]);

  const fill = useCallback(() => {
    if (!capability) return;
    const next: Record<string, unknown> = {};
    capability.fields.forEach((field) => {
      next[field.name] = sampleFor(field);
    });
    setDraft(next);
  }, [capability]);

  const authority = answer?.authority;

  return (
    <main style={{ font: "15px/1.45 system-ui, sans-serif", padding: 24, maxWidth: 960 }}>
      <h1>Community Bicycle Repair Co-op — Operator Console</h1>

      <section>
        <h2>Sign in</h2>
        <input
          type="password"
          placeholder="bearer token from the deploy environment"
          value={token}
          onChange={(event) => setToken(event.target.value)}
        />
        <button onClick={connect}>Connect</button>
        {status === 401 && <span role="alert"> refused (401)</span>}
      </section>

      <section>
        <h2>Log a record</h2>
        <select value={selected} onChange={(event) => setSelected(event.target.value)}>
          {capabilities.map((item) => (
            <option key={item.capability_id} value={item.capability_id}>
              {item.capability_id.replace(/_/g, " ")}
            </option>
          ))}
        </select>
        <button onClick={fill}>Fill sample</button>
        {capability?.fields.map((field) => (
          <label key={field.name} style={{ display: "block", margin: "6px 0" }}>
            {field.name}
            <input
              value={String(draft[field.name] ?? "")}
              onChange={(event) => setDraft({ ...draft, [field.name]: event.target.value })}
            />
          </label>
        ))}
        <button onClick={create}>Log record</button>
        <button onClick={list}>Load records</button>
      </section>

      <section>
        <h2>Answer</h2>
        {answer && (
          <>
            <p>
              authority layer {authority?.layer ?? "?"} · {authority?.layer_name ?? "procedures"} ·{" "}
              {authority?.precedence ?? "precedence.v1"}
            </p>
            {answer.ok === false && <p role="alert">refused ({status}): {answer.error}</p>}
            <pre>{JSON.stringify(answer.items ?? answer.decision ?? answer, null, 2)}</pre>
          </>
        )}
      </section>
    </main>
  );
