def _default_action(block_id: str) -> Optional[str]:
    try:
        from app.block_inputs import default_block_action

        return default_block_action(block_id)
    except Exception:
        return None


DEFAULT_ACTIONS = {}


def _module_name(block_id: str) -> str:
    return "app.blocks." + str(block_id).replace("-", "_")


def execute(block_id: str,
            payload: Optional[Dict[str, Any]] = None,
            action: Optional[str] = None,
            params: Optional[Dict[str, Any]] = None,
            **kwargs: Any) -> Dict[str, Any]:
    """Run one action on one block and return its envelope."""
    block_id = str(block_id or "").strip()
    if not block_id:
        return {"ok": False, "status": "error",
                "error": "Unknown block: %r" % block_id,
                "error_kind": "unknown_block"}

    verb = action if action is not None else _default_action(block_id)
    if verb is None:
        return {"ok": False, "status": "error",
                "error": "Unknown action: None", "error_kind": "unknown_action"}

    try:
        module = importlib.import_module(_module_name(block_id))
    except ImportError:
        return {"ok": False, "status": "error",
                "error": "Unknown block: %s" % block_id,
                "error_kind": "unknown_block"}

    body = dict(payload) if isinstance(payload, dict) else {}
    merged = dict(params) if isinstance(params, dict) else {}
    if merged:
        body = {**body, **merged}
    if kwargs:
        body = {**body, **kwargs}

    answer = module.handle(body, action=str(verb), params=None)
    if not isinstance(answer, dict):
        return {"ok": False, "status": "error",
                "error": "%s answered a non-envelope" % block_id,
                "error_kind": "invalid_answer"}
    return answer
