from typing import Any, Dict, Optional

from app.blocks._common import first_text, ok, refuse, unknown_action

AUTHORED_BY = "codewhale exec"

ACTIONS = ("capture", "store", "ingest", "read", "list")


def handle(payload: Dict[str, Any], action: Optional[str] = None,
           params: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    body = dict(payload or {})
    if params:
        body.update(params)
    verb = (action or "").strip().lower()
    if verb not in ACTIONS:
        return unknown_action(action)
    if verb == "list":
        captured = body.get("items")
        return ok(items=list(captured) if isinstance(captured, list) else [])
    content = first_text(
        body, "content", "text", "record", "summary", "description",
        "fault_description", "reference",
    )
    if not content:
        return refuse("capture requires content", "missing_required_input")
